def bfs_with_8_and_0(grid, target_value):
    """Find all cells reachable from target_value through 0 and target_value"""
    rows = len(grid)
    cols = len(grid[0])

    walkable = {0, target_value}
    targets = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == target_value]

    visited = set()
    dist = {}
    queue = deque()

    for t in targets:
        visited.add(t)
        dist[t] = 0
        queue.append((t[0], t[1], 0))

    while queue:
        r, c, d = queue.popleft()

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] in walkable and (nr, nc) not in visited:
                visited.add((nr, nc))
                dist[(nr, nc)] = d + 1
                queue.append((nr, nc, d + 1))

    return dist

